"""
UE Id  Type  State   IP addresses     NAT IP addresses  Location  MME  UEC  Group-ID  Group-name
--------------------------------------------------------------------------------------------------
1    INT   ACTIVE  1.7.0.1* (PDN1)  11.7.0.1 (PDN1)   1.1       1    1    -         -
"""
UeDispResult = namedtuple(
    "UeDispResult", "ue_id type state ip nat_ip location mme uec group_id group_name enb_id cell_id"
)


class EgateOutputParsingError(Exception):
    pass


class BearerDispResultTable(object):
    UE_REGEX = r'UE (\d+)'
    BEARER_DISP_REGEX = r'UE %s.*-{2,}(?:\r\n|\n|\r)(.*?)={2,}'

    def __init__(self):
        self.bearer_disp_result = {}

    def parse(self, bearer_disp_result_raw):
        bearer_disp_result = re.sub(r'\x1b..', '', bearer_disp_result_raw)
        logger.debug(repr(self.bearer_disp_result))
        for ue_id in re.findall(self.UE_REGEX, bearer_disp_result, re.DOTALL):
            self._parse_bearer_disp_result(ue_id, bearer_disp_result)

    def _parse_bearer_disp_result(self, ue_id, bearer_disp_result):
        try:
            table_lines = (
                re.search(self.BEARER_DISP_REGEX % ue_id, bearer_disp_result, re.DOTALL).group(1).splitlines()
            )
            self.bearer_disp_result[int(ue_id)] = dict([self._parse_bearer_line(line) for line in table_lines if line])
            logger.debug(self.bearer_disp_result)
        except ValueError:
            raise EgateOutputParsingError("Could not parse output: {}".format(repr(bearer_disp_result)))

    def _parse_bearer_line(self, line):
        split_line = re.split(r'[ ]+', line.strip())
        id_line, ebi, rbi, lcid, scglcid, rlc, lcg, lcp, rohc, maxcid, rohcctx, pdn, qci = split_line[:13]

        gbr, mbr = self._get_mbr_and_gbr(split_line)

        return (
            id_line.replace("*", ''),
            {
                'ebi': ebi,
                'rbi': rbi,
                'lcid': lcid,
                'scglcid': scglcid,
                'rlc': rlc,
                'lcg': lcg,
                'lcp': lcp,
                'rohc': rohc,
                'maxcid': maxcid,
                'rohcctx': rohcctx,
                'pdn': pdn,
                'qci': qci,
                'mbr': mbr,
                'gbr': gbr,
            },
        )

    def _get_mbr_and_gbr(self, line):
        """
        Line can take one of two forms. It can contain 15 or 17 elements. This method extracts last two of them.
        Example content:
        8*  5    4    3     -    AM12  3    12   -     -       -         1*   8    -            -
        1   6    5    4     -    UM7   1    5    -     -       -         1*   1    UL=31 DL=31  UL=31 DL=31
        """
        try:
            mbr = "{} {}".format(*line[13:15])
            gbr = "{} {}".format(*line[15:17])
        except IndexError:
            mbr, gbr = line[13:]
        return gbr, mbr


class UeDispResultTable(object):
    UE_DATA_REGEX = re.compile(r'Configured UEs.*?-(?:\r\n|\n|\r)(.*?)={2,}', re.DOTALL)
    LOCATION_INDEX = 5

    def __init__(self):
        self.ues_disp_result = []

    def parse(self, ue_disp_result_raw):
        ue_disp_result = re.sub(r'\x1b..', '', ue_disp_result_raw)  # removing control characters from input
        result_lines = self._get_ue_disp_result_as_lines_of_ue_data(ue_disp_result)
        logger.debug(repr(result_lines))
        self.ues_disp_result = [self._create_ue_disp_result(line) for line in result_lines]

    @property
    def active_ues(self):
        ues = OrderedDict()
        for ue_disp in self.ues_disp_result:
            ues[ue_disp.ue_id] = {'enb_id': ue_disp.enb_id, 'cell_id': ue_disp.cell_id}
        return ues

    def _create_ue_disp_result(self, line):
        values = re.split(r'[ ]{2,}', line.strip())
        location = values[self.LOCATION_INDEX]
        try:
            values += location.split('.')
            return UeDispResult(*values)
        except AttributeError:
            raise EgateOutputParsingError("Can't split location member, it may be uninitialized: {}".format(location))
        except ValueError:
            raise EgateOutputParsingError(
                'Ue location found doesn\'t match pattern "enb_id.cell_id" ({} was given)'.format(location)
            )

    def _get_ue_disp_result_as_lines_of_ue_data(self, ue_disp_result):
        """
        Method searches for following lines:

        Configured UEs
        ==========================================================================================
        UE Id  Type  State   IP addresses     NAT IP addresses  Location  MME  UEC  Group-ID  Group-name
        ------------------------------------------------------------------------------------------
        101    INT   ACTIVE  1.7.0.1* (PDN1)  11.7.0.1 (PDN1)   1.1       1    1    -         -
        102    INT   ACTIVE  1.7.0.2* (PDN1)  11.7.0.2 (PDN1)   1.1       1    1    -         -
        103    INT   ACTIVE  1.7.0.3* (PDN1)  11.7.0.3 (PDN1)   1.2       1    1    -         -
        ===============================================================================================

        And splits them into line list:
        ['        101    -      INT   ACTIVE  1.7.0.1* (PDN1)  11.7.0.1 (PDN1)   1.1       1    1',
         '        102    -      INT   ACTIVE  1.7.0.2* (PDN1)  11.7.0.2 (PDN1)   1.1       1    1',
         '        103    -      INT   ACTIVE  1.7.0.3* (PDN1)  11.7.0.3 (PDN1)   1.2       1    1']

        :param ue_disp_result:
        :return:
        """
        logger.debug(repr(ue_disp_result))
        try:
            return self.UE_DATA_REGEX.search(ue_disp_result).group(1).splitlines()
        except AttributeError:
            raise EgateOutputParsingError(
                "Could not find ue_disp result in given string: {}".format(repr(ue_disp_result))
            )
        except TypeError:
            raise EgateOutputParsingError(
                "Could not find ue_disp result in given string: {}".format(repr(ue_disp_result))
            )


class ta5g_bearers(object):
    BEARER_ADD_CMD = "bearer_add ue={ue_id} {params}"
    PDN_CONNECT_UE_CMD = "pdn_connect_ue ue={0} {1}"
    BEARER_ADD_PASS_REGEX = "UE{}: +PGW-initiated +Bearer +Creation. +Bearer-{}.*"
    BEARER_ADD_FAIL_REGEX = "UE{}: +PGW-initiated +Bearer +Creation. SGW failed to create Bearer-{} with cause=.*"
    PDN_CONNECT_PASS_REGEX = "UE{}: +PDN +connectivity +procedure +for +PDN {}.*"
    ERAB_SETUP_RESPONSE = '{}:S1AP_E-RABSetupResponse'
    INITIAL_CONTEXT_SETUP_RESPONSE = '{}:S1AP_InitialContextSetupResponse'

    def __init__(self):
        self.wtssim = lazy_import('ute_wtssim')
        self.compiled_ue_disp_regexp = re.compile(r'Configured UEs.*-(?:\r\n|\n|\r)(.*?)={2,}', re.DOTALL)
        self.bearer_disp_regexp = r'UE %s.*-{2,}(?:\r\n|\n|\r)(.*?)={2,}'
        self.ue_result_table = UeDispResultTable()
        self.bearer_disp_result = BearerDispResultTable()

    def add_bearer(self, ue_id, bearer_id, pass_regexp, **kwargs):
        """
        :param ue_id: Ue id to add the bearer
        :param bearer_id: Bearer id  will be added to ue
        """
        logger.info("Adding bearer {} to UE {}".format(id, ue_id))
        if 'filter' in kwargs.keys():
            filter = kwargs['filter']
        else:
            filter = int(bearer_id) - 1
        if 'precedence' in kwargs.keys():
            precedence = kwargs['precedence']
        else:
            precedence = bearer_id
        if 'by' in kwargs.keys():
            by = kwargs['by']
        else:
            by = None
        params = self._as_bearer_params(bearer_id, filter, precedence, by)
        self.wtssim.execute_egate_command(
            cmd=self.BEARER_ADD_CMD.format(ue_id=ue_id, params=params),
            pass_regexp=pass_regexp,
            timeout=15
        )

    def _build_result_regex_for_bearer_add_cmd(self, ue_id, bearers_params, bearers_to_reject_params):
        return self._build_cmd_pass_regex(
            ue_id, 'id', bearers_params, self.BEARER_ADD_PASS_REGEX
        ) + self._build_cmd_pass_regex(ue_id, 'id', bearers_to_reject_params, self.BEARER_ADD_FAIL_REGEX)

    @staticmethod
    def _build_cmd_pass_regex(ue_id, token, params, regex):
        tokens = re.findall(r'{}=(\d+)'.format(token), params)
        return "".join(regex.format(ue_id, t) for t in tokens)

    def add_bearers_to_ue(self, ue_id, bearers_params="", bearers_to_reject_params=""):
        """
        Sends ERAB Setup with given bearers parameters
        :param ue_id: Ue id to add the bearers
        :param bearers_params: Bearers params as a string
        :param bearers_to_reject_params: Bearers which will be rejected; Bearers params as a string
        """
        full_bearers_params = "{} {}".format(bearers_params, bearers_to_reject_params).strip()
        add_bearers_cmd = self.BEARER_ADD_CMD.format(ue_id=ue_id, params=full_bearers_params)
        logger.info("Adding bearers using {0} to UE {1}".format(full_bearers_params, ue_id))
        add_bearers_cmd_pass_regex = self._build_result_regex_for_bearer_add_cmd(
            ue_id, bearers_params, bearers_to_reject_params
        )
        self.wtssim.execute_egate_command_and_wait_for_data(
            cmd=add_bearers_cmd, pass_regexp=add_bearers_cmd_pass_regex, timeout=5
        )

    def connect_ue_to_pdn(self, ue_id, pdn_params):
        """
        Sends PDN CONNECTIVITY REQ to given pdn and then ERAB Setup
        :param ue_id: Ue id to add the bearers
        :param pdn_params: Pdn params as a string
        """
        pdn_connect_cmd = self.PDN_CONNECT_UE_CMD.format(ue_id, pdn_params)
        logger.info("Connecting UE{0} to PDN {1}".format(ue_id, pdn_params))
        pdn_connect_cmd_pass_regex = self._build_cmd_pass_regex(ue_id, 'pdn', pdn_params, self.PDN_CONNECT_PASS_REGEX)
        self.wtssim.execute_egate_command_and_wait_for_data(
            cmd=pdn_connect_cmd, pass_regexp=pdn_connect_cmd_pass_regex, timeout=5
        )

    def add_bearer_to_ue_and_expect_ue_context_release(self, ue_id, bearer_id):
        """
        :param ue_id: Ue id to add the bearer
        :param bearer_id: Bearer id  will be added to ue
        """
        logger.info("Adding bearer {} to UE {}".format(bearer_id, ue_id))
        bearer_add_output = self.wtssim.execute_egate_command_and_wait_for_data(
            cmd="bearer_add ue={0} id={1} filter={2} precedence={1}".format(ue_id, bearer_id, int(bearer_id) - 1),
            pass_regexp=self.BEARER_ADD_PASS_REGEX.format(ue_id, bearer_id),
            fail_regexp=self.BEARER_ADD_FAIL_REGEX.format(ue_id, bearer_id),
            timeout=5,
        )
        msg = ": IS IDLE"
        assert msg in bearer_add_output, "Bearer was added, but no ue context release was performed!"

    def add_bearer_to_ue_and_expect_rejection(self, ue_id, bearer_id):
        """
        :param ue_id: Ue id to add the bearer
        :param bearer_id: Bearer id  will be added to ue
        """
        logger.info("Adding bearer {} to UE {}".format(bearer_id, ue_id))
        self.wtssim.execute_egate_command_and_wait_for_data(
            cmd="bearer_add ue={0} id={1} filter={2} precedence={1}".format(ue_id, bearer_id, int(bearer_id) - 1),
            pass_regexp=self.BEARER_ADD_FAIL_REGEX.format(ue_id, bearer_id),
            fail_regexp="S1:E-RAB_RELEASE_INDICATION(e_RAB_ID=6, Cause: RAN radio resources not available). eNB=1",
            timeout=5,
        )

    def get_active_ues_in_cell(self, cell_id, enb_id='1'):
        """
        Returns ues active in given cell
        :param cell_id:
        :param enb_id:
        :return:
        """
        enb_id = str(enb_id)
        cell_id = self._as_array(cell_id)

        ues = self._get_active_ues()
        ues_in_cell = {
            ue_id: ue_data for ue_id, ue_data in list(ues.items()) if self._ue_in_given_cells(ue_data, cell_id, enb_id)
        }

        logger.debug("Ues in location {}.{}:\n{}".format(enb_id, cell_id, ues))
        return ues_in_cell

    def get_number_of_bearers_in_cell(self, cell_id, enb_id='1', qci='all'):
        """
        :param cell_id: Single cell id or list of cell ids (sums bearers in cells)
        :param enb_id:
        :param qci: Default: 'all' - counts all bearers regardless of qci,
                    different value counts only bearers with provied qci
        :return:
        """
        enb_id = str(enb_id)
        qci = str(qci)
        cell_id = self._as_array(cell_id)

        ues = self._get_active_ue_bearers()
        ues_in_cell = {
            ue_id: ue_data for ue_id, ue_data in list(ues.items()) if self._ue_in_given_cells(ue_data, cell_id, enb_id)
        }

        if qci == 'all':
            bearer_count = sum([len(ue['bearers']) for ue in list(ues_in_cell.values())])
        else:
            bearer_count = sum(
                count_if(list(ue['bearers'].values()), lambda bearer: bearer['qci'] == qci)
                for ue in list(ues_in_cell.values())
            )
        logger.info(
            "Number of bearers in location {}.{} with qci {} is {}".format(enb_id, cell_id, repr(qci), bearer_count)
        )
        return bearer_count

    def verify_that_cell_has_given_number_of_bearers_active(self, cell_id, num_of_bearers, enb_id='1', qci='all'):
        """

        :param cell_id: Single cell id or list of cell ids (in case of list active bearers are summed)
        :param num_of_bearers:
        :param enb_id:
        :param qci: Default: 'all' - counts all bearers regardless of qci,
                    different value counts only bearers with provied qci
        :return:
        """
        actual = self.get_number_of_bearers_in_cell(cell_id=cell_id, enb_id=enb_id, qci=qci)
        assert (
            int(num_of_bearers) == actual
        ), "Number of active bearers is different from expected! (Expected: {}; Actual: {})".format(
            num_of_bearers, actual
        )

    def get_ue_bearers(self, ue_id):
        """
        Returns dictionary containing list of active ue bearers
        :param ue_id:
        :return:
        """
        bearer_disp_result = self.wtssim.execute_egate_command_and_wait_for_data(
            cmd='bearer_disp ue={} at=ue'.format(ue_id), timeout=5, pass_regexp=self.bearer_disp_regexp % ue_id
        )
        self.bearer_disp_result.parse(bearer_disp_result)
        return self.bearer_disp_result.bearer_disp_result[int(ue_id)]

    def get_ue_bearer_count(self, ue_id):
        """
        Returns number of active bearers in ue
        :param ue_id:
        :return:
        """
        return len(self.get_ue_bearers(ue_id))

    def verify_that_ue_has_given_number_of_bearers(self, ue_id, bearer_count):
        """

        :param ue_id:
        :param bearer_count:
        :return:
        """
        ue_bearer_count = self.get_ue_bearer_count(ue_id)
        assert ue_bearer_count == int(bearer_count), "UE {} has {} bearers (expected {})".format(
            ue_id, ue_bearer_count, bearer_count
        )

    def add_multiple_bearers_for_multiple_ues(self, last_ue_id, first_bearer_id, last_bearer_id, first_ue_id):
        """
        :param first_ue_id: First ue id to add the bearer
        :param last_ue_id: Last ue id to add the bearer
        :param first_bearer_id: First bearer id which will be added to ue
        :param last_bearer_id: Last bearer id which will be added to ue
        """
        for ue_id in range(int(first_ue_id), int(last_ue_id) + 1):
            self.add_multiple_bearers_to_ue(ue_id, first_bearer_id, last_bearer_id)

    def delete_bearer_from_ue(self, ue_id, bearer_id):
        """
        :param ue_id: Id ue to delete the bearer
        :param bearer_id: Bearer id which will be deleted from ue
        """
        logger.info("Deleting bearer {} from UE {}".format(bearer_id, ue_id))
        self.wtssim.execute_egate_command_and_wait_for_data(
            cmd="bearer_del ue={} id={}".format(ue_id, bearer_id),
            pass_regexp="UE{}: Bearer-{} (.*) deleted in result of PGW-initiated Bearer Deletion procedure".format(
                ue_id, bearer_id
            ),
            timeout=10,
        )

    def trigger_bearer_release(self, ue_id, bearer_id):
        """
        :param ue_id: Id ue to delete the bearer
        :param bearer_id: Bearer id which will be deleted from ue
        Disclaimer: This method does not check or ensure successful
                    Bearer Deletion procedure.
        """
        logger.info("Triggereing Release Command for bearer {} from UE {}".format(bearer_id, ue_id))
        self.wtssim.execute_egate_command(cmd="bearer_del ue={} id={}".format(ue_id, bearer_id), timeout=10)

    def delete_multiple_bearers_from_ue(self, ue_id, first_bearer_id, last_bearer_id):
        """
        :param ue_id: Id ue to delete the bearer
        :param first_bearer_id: First bearer id which will be deleted from ue
        :param last_bearer_id: Last bearer id which will be deleted from ue
        """
        for bearer_id in range(int(first_bearer_id), int(last_bearer_id) + 1):
            self.delete_bearer_from_ue(ue_id, bearer_id)

    def display_ue_bearers(self, ue_id, at="sgw"):
        """
        :param ue_id:
        """
        self.wtssim.execute_egate_command_and_wait_for_data(cmd="bearer_disp ue={} at={}".format(ue_id, at))

    def modify_ue_bearer(self, ue_id, bearer_id, optional_parameters=""):
        """
        :param ue_id: Ue id which will be modified
        :param bearer_id: Bearer id which will be modified
        :param optional_parameters: Parameters which will be modified
        """
        self.wtssim.execute_egate_command_and_wait_for_data(
            cmd="bearer_mod ue={} id={} {}".format(ue_id, bearer_id, optional_parameters)
        )

    def send_gtp_error_indication_from_sgw_to_enb(self, ue_id, bearer_id):
        """
        :param ue_id:
        :param bearer_id:
        """
        self.wtssim.execute_egate_command_and_wait_for_data(
            cmd="ue_sgw_inject_error_ind ue={} bearer={}".format(ue_id, bearer_id)
        )

    def verify_if_erab_setup_response_contains_proper_amount_of_established_bearers(
        self, bearer_amount, flow_alias='ERAB_SETUP', mme_alias='MME'
    ):
        _verify_length_of_field(
            flow_alias=flow_alias,
            message_alias=self.ERAB_SETUP_RESPONSE.format(mme_alias),
            field_name='E-RABSetupListBearerSURes',
            length=bearer_amount,
        )

    def verify_if_erab_setup_response_contains_proper_amount_of_rejected_bearers(
        self, bearer_amount, flow_alias='ERAB_SETUP', mme_alias='MME'
    ):
        _verify_length_of_field(
            flow_alias=flow_alias,
            message_alias=self.ERAB_SETUP_RESPONSE.format(mme_alias),
            field_name='E-RABList',
            length=bearer_amount,
        )

    def verify_if_initial_context_setup_response_contains_proper_amount_of_established_bearers(
        self, bearer_amount, flow_alias='INITIAL_CONTEXT_SETUP', mme_alias='MME'
    ):
        _verify_length_of_field(
            flow_alias=flow_alias,
            message_alias=self.INITIAL_CONTEXT_SETUP_RESPONSE.format(mme_alias),
            field_name='E-RABSetupListCtxtSURes',
            length=bearer_amount,
        )

    def _get_active_ues(self):
        ue_disp_result = self.wtssim.execute_egate_command_and_wait_for_data(
            cmd="ue_disp state=ACTIVE", timeout=5, pass_regexp=self.compiled_ue_disp_regexp
        )

        self.ue_result_table.parse(ue_disp_result)
        return self.ue_result_table.active_ues

    def _get_active_ue_bearers(self):
        ues = self._get_active_ues()
        for ue in ues:
            ues[ue]['bearers'] = self.get_ue_bearers(ue)
        logger.debug(pformat(ues))
        return ues

    def _ue_in_given_cells(self, ue, cells_ids, enb_id):
        return ue['cell_id'] in cells_ids and ue['enb_id'] == enb_id

    def _as_array(self, cell_id):
        if isinstance(cell_id, list):
            cell_id = [str(cell) for cell in cell_id]
        else:
            cell_id = [str(cell_id)]
        return cell_id

    def _as_bearer_params(self, _id=None, _filter=None, _precedence=None, _by=None):
        params = ""
        params += "id={}".format(_id) if _id is not None else ""
        params += " filter={}".format(_filter) if _filter is not None else ""
        params += " precedence={}".format(_precedence) if _precedence is not None else ""
        params += " by={}".format(_by) if _by is not None else ""
        return params


def _verify_length_of_field(flow_alias, message_alias, field_name, length):
    from ta_messaging.message_flows import get_flow

    message_field = get_flow(flow_alias).get_message(message_alias).get_value_by_unique_key(field_name)
    logger.debug(message_field)
    assert len(message_field) == int(length)
